<div class="panel"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Receipt') ?></th><th><?= __('Date') ?></th><th><?= __('Customer') ?></th><th><?= __('Into') ?></th><th class="num"><?= __('Amount') ?></th><th><?= __('Reference') ?></th><th></th></tr></thead>
